import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if we have a strong driver (p < 0.01, |t| > 3)
    strong_drivers = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'cohort'):
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean())
            if abs(t_stat) > 3 and feats.y.mean() > 0.1:
                strong_drivers.append(fid)

    # If no strong driver found, look for interaction terms
    if not strong_drivers:
        # Find features with strong associations (p < 0.05, |t| > 2)
        candidates = []
        for i, fid in enumerate(feats.ids):
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean())
            if abs(t_stat) > 2 and feats.y.mean() > 0.1:
                candidates.append((fid, abs(t_stat)))

        # Sort by strength
        candidates.sort(key=lambda x: x[1], reverse=True)
        drivers = [fid for fid, _ in candidates[:min(MAX_DRIVERS, len(candidates))]]

        # For small models, just return the strongest features
        return Design(
            drivers=tuple(drivers),
            columns=tuple(drivers),
            products=(),
            loadings={}
        )

    # We have a strong driver, use it
    driver = strong_drivers[0]

    # Simple approach: return just the driver
    return Design(
        drivers=(driver,),
        columns=(driver,),
        products=(),
        loadings={driver: 1.0}
    )

